static void mix_mono_at(StereoBuffer& dst, const Buffer& src,
                        double t_sec, float gain, int sr)
{
    const size_t off = (size_t)(t_sec * sr);
    for (size_t i = 0; i < src.size() && off + i < dst.size(); ++i) {
        dst.L[off + i] += src[i] * gain;
        dst.R[off + i] += src[i] * gain;
    }
}

static void mix_stereo_at(StereoBuffer& dst, const StereoBuffer& src,
                          double t_sec, float gain, int sr)
{
    const size_t off = (size_t)(t_sec * sr);
    for (size_t i = 0; i < src.size() && off + i < dst.size(); ++i) {
        dst.L[off + i] += src.L[i] * gain;
        dst.R[off + i] += src.R[i] * gain;
    }
}

// Piccolo — pure upper-register flute with breath and air
static Buffer make_piccolo(double freq, double dur, int sr)
{
    double d = std::max(0.02, dur);
    Buffer buf = make_buffer(d, sr);
    Oscillator o1(WaveShape::Sine, freq,       0.58);
    Oscillator o2(WaveShape::Sine, freq * 2.0, 0.20);
    Oscillator o3(WaveShape::Sine, freq * 3.0, 0.08);
    NoiseGenerator ng(31u);
    double vp = 0.0;
    for (size_t i = 0; i < buf.size(); ++i) {
        vp += TWO_PI * 6.2 / sr;
        if (vp >= TWO_PI) vp -= TWO_PI;
        double t = (double)i / sr;
        double ve = std::min(1.0, std::max(0.0, (t - 0.05) / 0.06));
        double vd = std::sin(vp) * freq * (std::pow(2.0, 8.0/1200.0) - 1.0) * ve;
        o1.frequency = freq + vd;
        float breath = ng.tick_white() * 0.018f * (float)std::min(1.0, t / 0.04);
        buf[i] = o1.tick(sr) + o2.tick(sr) + o3.tick(sr) + breath;
    }
    HighPassFilter hpf(500.0, sr); hpf.process(buf);
    BiquadEQ air(BiquadEQ::Type::HighShelf, 6000.0, 2.0, 0.7);
    air.process(buf, sr);
    SVFilter lp(SVFilter::Mode::LowPass, 6500.0, 0.65); lp.process(buf, sr);
    double rel = std::min(0.05, d * 0.18);
    ADSR env(0.008, d * 0.06, 0.88, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

// Flute — sine blend with vibrato and gentle breath
static Buffer make_flute(double freq, double dur, int sr)
{
    double d = std::max(0.02, dur);
    Buffer buf = make_buffer(d, sr);
    Oscillator o1(WaveShape::Sine, freq,       0.55);
    Oscillator o2(WaveShape::Sine, freq * 2.0, 0.22);
    Oscillator o3(WaveShape::Sine, freq * 3.0, 0.07);
    NoiseGenerator ng(29u);
    double vp = 0.0;
    for (size_t i = 0; i < buf.size(); ++i) {
        vp += TWO_PI * 5.8 / sr;
        if (vp >= TWO_PI) vp -= TWO_PI;
        double t = (double)i / sr;
        double ve = std::min(1.0, std::max(0.0, (t - 0.08) / 0.08));
        double vd = std::sin(vp) * freq * (std::pow(2.0, 7.0/1200.0) - 1.0) * ve;
        o1.frequency = freq + vd;
        float breath = ng.tick_white() * 0.015f * (float)std::min(1.0, t / 0.05);
        buf[i] = o1.tick(sr) + o2.tick(sr) + o3.tick(sr) + breath;
    }
    HighPassFilter hpf(300.0, sr); hpf.process(buf);
    SVFilter lp(SVFilter::Mode::LowPass, 5000.0, 0.65); lp.process(buf, sr);
    double rel = std::min(0.06, d * 0.20);
    ADSR env(0.010, d * 0.08, 0.84, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

// Oboe — nasal sine blend, formant around 1.1kHz
static Buffer make_oboe(double freq, double dur, int sr)
{
    double d = std::max(0.02, dur);
    Buffer buf = make_buffer(d, sr);
    Oscillator o1(WaveShape::Sine, freq,       0.55);
    Oscillator o2(WaveShape::Sine, freq * 2.0, 0.26);
    Oscillator o3(WaveShape::Sine, freq * 3.0, 0.12);
    Oscillator o4(WaveShape::Sine, freq * 4.0, 0.05);
    double vp = 0.0;
    for (size_t i = 0; i < buf.size(); ++i) {
        vp += TWO_PI * 5.5 / sr;
        if (vp >= TWO_PI) vp -= TWO_PI;
        double t = (double)i / sr;
        double ve = std::min(1.0, std::max(0.0, (t - 0.10) / 0.08));
        double vd = std::sin(vp) * freq * (std::pow(2.0, 6.0/1200.0) - 1.0) * ve;
        o1.frequency = freq + vd;
        buf[i] = o1.tick(sr) + o2.tick(sr) + o3.tick(sr) + o4.tick(sr);
    }
    BiquadEQ nasal(BiquadEQ::Type::Peak, 1100.0, 2.5, 2.0);
    nasal.process(buf, sr);
    SVFilter lp(SVFilter::Mode::LowPass, 2800.0, 0.62); lp.process(buf, sr);
    double rel = std::min(0.06, d * 0.18);
    ADSR env(0.012, d * 0.08, 0.80, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

// Clarinet — cylindrical bore: odd harmonics, hollow tone
static Buffer make_clarinet(double freq, double dur, int sr)
{
    double d = std::max(0.02, dur);
    Buffer buf = make_buffer(d, sr);
    Oscillator o1(WaveShape::Sine, freq,       0.60);
    Oscillator o2(WaveShape::Sine, freq * 3.0, 0.22);
    Oscillator o3(WaveShape::Sine, freq * 5.0, 0.10);
    Oscillator o4(WaveShape::Sine, freq * 2.0, 0.06);
    for (auto& s : buf) s = o1.tick(sr) + o2.tick(sr) + o3.tick(sr) + o4.tick(sr);
    SVFilter lp(SVFilter::Mode::LowPass, 2500.0, 0.62); lp.process(buf, sr);
    BiquadEQ throat(BiquadEQ::Type::Peak, 1500.0, 2.0, 2.0);
    throat.process(buf, sr);
    double rel = std::min(0.06, d * 0.18);
    ADSR env(0.014, d * 0.08, 0.80, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

// Soprano / alto sax → rendered as bright clarinet-oboe hybrid
static Buffer make_sax(double freq, double dur, int sr)
{
    double d = std::max(0.02, dur);
    Buffer buf = make_buffer(d, sr);
    Oscillator o1(WaveShape::Sine, freq,       0.52);
    Oscillator o2(WaveShape::Sine, freq * 2.0, 0.28);
    Oscillator o3(WaveShape::Sine, freq * 3.0, 0.14);
    Oscillator o4(WaveShape::Sine, freq * 4.0, 0.05);
    double vp = 0.0;
    for (size_t i = 0; i < buf.size(); ++i) {
        vp += TWO_PI * 5.2 / sr;
        if (vp >= TWO_PI) vp -= TWO_PI;
        double t = (double)i / sr;
        double ve = std::min(1.0, std::max(0.0, (t - 0.08) / 0.08));
        double vd = std::sin(vp) * freq * (std::pow(2.0, 7.0/1200.0) - 1.0) * ve;
        o1.frequency = freq + vd;
        buf[i] = o1.tick(sr) + o2.tick(sr) + o3.tick(sr) + o4.tick(sr);
    }
    BiquadEQ mid(BiquadEQ::Type::Peak, 900.0, 2.0, 1.8);
    mid.process(buf, sr);
    SVFilter lp(SVFilter::Mode::LowPass, 2600.0, 0.62); lp.process(buf, sr);
    double rel = std::min(0.06, d * 0.18);
    ADSR env(0.010, d * 0.08, 0.80, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

// French horn — round, mellow sine blend
static Buffer make_horn(double freq, double dur, int sr)
{
    double d = std::max(0.02, dur);
    Buffer buf = make_buffer(d, sr);
    Oscillator o1(WaveShape::Sine, freq,       0.55);
    Oscillator o2(WaveShape::Sine, freq * 2.0, 0.24);
    Oscillator o3(WaveShape::Sine, freq * 3.0, 0.12);
    Oscillator o4(WaveShape::Sine, freq * 4.0, 0.05);
    for (auto& s : buf) s = o1.tick(sr) + o2.tick(sr) + o3.tick(sr) + o4.tick(sr);
    BiquadEQ bell(BiquadEQ::Type::Peak, 1000.0, 2.0, 1.8);
    bell.process(buf, sr);
    SVFilter lp(SVFilter::Mode::LowPass, 1800.0, 0.62); lp.process(buf, sr);
    double atk = std::min(0.06, d * 0.14);
    double rel = std::min(0.14, d * 0.18);
    DAHDSR env(0.0, atk, 0.0, d * 0.10, 0.62, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

// Trumpet — brighter sine harmonics, fast attack
static Buffer make_trumpet(double freq, double dur, int sr)
{
    double d = std::max(0.02, dur);
    Buffer buf = make_buffer(d, sr);
    Oscillator o1(WaveShape::Sine, freq,       0.52);
    Oscillator o2(WaveShape::Sine, freq * 2.0, 0.26);
    Oscillator o3(WaveShape::Sine, freq * 3.0, 0.14);
    Oscillator o4(WaveShape::Sine, freq * 4.0, 0.06);
    for (auto& s : buf) s = o1.tick(sr) + o2.tick(sr) + o3.tick(sr) + o4.tick(sr);
    BiquadEQ peak(BiquadEQ::Type::Peak, 1500.0, 2.5, 2.0);
    peak.process(buf, sr);
    SVFilter lp(SVFilter::Mode::LowPass, 2200.0, 0.62); lp.process(buf, sr);
    double atk = std::min(0.04, d * 0.10);
    double rel = std::min(0.10, d * 0.15);
    DAHDSR env(0.0, atk, 0.0, d * 0.06, 0.60, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

// Piano — sine+triangle blend, decaying tone
static Buffer make_piano(double freq, double dur, int sr)
{
    double d = std::max(0.03, dur);
    Buffer buf = make_buffer(d, sr);
    Oscillator o1(WaveShape::Sine,     freq,       0.55);
    Oscillator o2(WaveShape::Triangle, freq * 2.0, 0.22);
    Oscillator o3(WaveShape::Sine,     freq * 3.0, 0.10);
    Oscillator o4(WaveShape::Sine,     freq * 0.5, 0.10);
    for (auto& s : buf) s = o1.tick(sr) + o2.tick(sr) + o3.tick(sr) + o4.tick(sr);
    SVFilter lp(SVFilter::Mode::LowPass, 3000.0, 0.62); lp.process(buf, sr);
    double rel = std::min(0.50, d * 0.35);
    ADSR env(0.003, d * 0.10, 0.55, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

// String section — bowed violin/viola tone with vibrato
static StereoBuffer make_strings(double freq, double dur, int sr)
{
    double d = std::max(0.03, dur);
    Buffer mono = make_buffer(d, sr);
    Oscillator o1(WaveShape::Sine, freq,        0.50);
    Oscillator o2(WaveShape::Sine, freq * 2.0,  0.26);
    Oscillator o3(WaveShape::Sine, freq * 3.0,  0.12);
    Oscillator o4(WaveShape::Sine, freq * 0.5,  0.08);
    double vp = 0.0;
    const double vd = freq * (std::pow(2.0, 6.0/1200.0) - 1.0);
    for (size_t i = 0; i < mono.size(); ++i) {
        vp += TWO_PI * 5.4 / sr;
        if (vp >= TWO_PI) vp -= TWO_PI;
        double t = (double)i / sr;
        double ve = std::min(1.0, std::max(0.0, (t - 0.12) / 0.10));
        o1.frequency = freq + std::sin(vp) * vd * ve;
        mono[i] = o1.tick(sr) + o2.tick(sr) + o3.tick(sr) + o4.tick(sr);
    }
    BiquadEQ body(BiquadEQ::Type::Peak, 2200.0, 1.5, 2.0);
    body.process(mono, sr);
    SVFilter lp(SVFilter::Mode::LowPass, 2800.0, 0.62); lp.process(mono, sr);
    double atk = std::min(0.08, d * 0.15);
    double rel = std::min(0.30, d * 0.22);
    DAHDSR env(0.0, atk, 0.0, d * 0.08, 0.62, rel);
    env.apply(mono, d, std::max(0.0, d - rel), sr);
    return haas_widen(mono, 10.0, sr);
}

// Viola — warmer, darker string tone
static Buffer make_viola(double freq, double dur, int sr)
{
    double d = std::max(0.03, dur);
    Buffer buf = make_buffer(d, sr);
    Oscillator o1(WaveShape::Sine, freq,       0.52);
    Oscillator o2(WaveShape::Sine, freq * 2.0, 0.24);
    Oscillator o3(WaveShape::Sine, freq * 3.0, 0.10);
    Oscillator o4(WaveShape::Sine, freq * 0.5, 0.10);
    double fl = 0.0;
    for (size_t i = 0; i < buf.size(); ++i) {
        fl += TWO_PI * 5.8 / sr;
        if (fl >= TWO_PI) fl -= TWO_PI;
        buf[i] = (o1.tick(sr) + o2.tick(sr) + o3.tick(sr) + o4.tick(sr))
                 * (1.0f + 0.03f * (float)std::sin(fl));
    }
    BiquadEQ body(BiquadEQ::Type::Peak, 600.0, 1.5, 1.8);
    body.process(buf, sr);
    SVFilter lp(SVFilter::Mode::LowPass, 2400.0, 0.62); lp.process(buf, sr);
    double atk = std::min(0.09, d * 0.18);
    double rel = std::min(0.28, d * 0.22);
    DAHDSR env(0.0, atk, 0.0, d * 0.10, 0.60, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

// Cello — warm low string
static Buffer make_cello(double freq, double dur, int sr)
{
    double d = std::max(0.03, dur);
    Buffer buf = make_buffer(d, sr);
    Oscillator o1(WaveShape::Sine, freq,       0.55);
    Oscillator o2(WaveShape::Sine, freq * 2.0, 0.22);
    Oscillator o3(WaveShape::Sine, freq * 0.5, 0.18);
    double fl = 0.0;
    for (size_t i = 0; i < buf.size(); ++i) {
        fl += TWO_PI * 5.5 / sr;
        if (fl >= TWO_PI) fl -= TWO_PI;
        buf[i] = (o1.tick(sr) + o2.tick(sr) + o3.tick(sr))
                 * (1.0f + 0.04f * (float)std::sin(fl));
    }
    BiquadEQ body(BiquadEQ::Type::Peak, 320.0, 1.8, 1.8);
    body.process(buf, sr);
    SVFilter lp(SVFilter::Mode::LowPass, 2000.0, 0.60); lp.process(buf, sr);
    double atk = std::min(0.10, d * 0.18);
    double rel = std::min(0.35, d * 0.25);
    DAHDSR env(0.0, atk, 0.0, d * 0.12, 0.60, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

// Contrabass — deep sine foundation
static Buffer make_contrabass(double freq, double dur, int sr)
{
    double d = std::max(0.02, dur);
    Buffer buf = make_buffer(d, sr);
    Oscillator o1(WaveShape::Sine, freq,       0.65);
    Oscillator o2(WaveShape::Sine, freq * 2.0, 0.20);
    Oscillator o3(WaveShape::Sine, freq * 3.0, 0.08);
    for (auto& s : buf) s = o1.tick(sr) + o2.tick(sr) + o3.tick(sr);
    SVFilter lp(SVFilter::Mode::LowPass, 280.0, 0.60); lp.process(buf, sr);
    double atk = std::min(0.12, d * 0.20);
    double rel = std::min(0.45, d * 0.28);
    DAHDSR env(0.0, atk, 0.0, d * 0.10, 0.62, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

// Saw/Square synth tracks → rendered as string ensemble pads
static StereoBuffer make_string_pad(double freq, double dur, int sr)
{
    double d = std::max(0.04, dur);
    Buffer mono = make_buffer(d, sr);
    Oscillator o1(WaveShape::Sine, freq,         0.48);
    Oscillator o2(WaveShape::Sine, freq * 2.0,   0.22);
    Oscillator o3(WaveShape::Sine, freq * 3.0,   0.10);
    Oscillator o4(WaveShape::Sine, freq * 0.5,   0.12);
    double vp = 0.0;
    const double vd = freq * (std::pow(2.0, 5.0/1200.0) - 1.0);
    for (size_t i = 0; i < mono.size(); ++i) {
        vp += TWO_PI * 5.2 / sr;
        if (vp >= TWO_PI) vp -= TWO_PI;
        double t = (double)i / sr;
        double ve = std::min(1.0, std::max(0.0, (t - 0.15) / 0.12));
        o1.frequency = freq + std::sin(vp) * vd * ve;
        mono[i] = o1.tick(sr) + o2.tick(sr) + o3.tick(sr) + o4.tick(sr);
    }
    SVFilter lp(SVFilter::Mode::LowPass, 2000.0, 0.60); lp.process(mono, sr);
    double atk = std::min(0.14, d * 0.20);
    double rel = std::min(0.40, d * 0.28);
    DAHDSR env(0.0, atk, 0.0, d * 0.10, 0.55, rel);
    env.apply(mono, d, std::max(0.0, d - rel), sr);
    return haas_widen(mono, 10.0, sr);
}

// Timpani
static Buffer make_timpani(double pitch = 80.0)
{
    const double dur = 1.40;
    Buffer buf = make_buffer(dur, SR);
    NoiseGenerator ng(41u);
    double phase = 0.0;
    for (size_t i = 0; i < buf.size(); ++i) {
        double t = (double)i / SR;
        double f = pitch * (1.0 + 0.10 * std::exp(-t * 14.0));
        phase += TWO_PI * f / SR;
        if (phase >= TWO_PI) phase -= TWO_PI;
        buf[i] = (float)(std::sin(phase) * std::exp(-t * 3.8))
               + ng.tick_white() * (float)std::exp(-t * 28.0) * 0.16f;
    }
    SVFilter lp(SVFilter::Mode::LowPass, 380.0, 0.75); lp.process(buf, SR);
    normalize(buf, 0.88f);
    return buf;
}

static Buffer make_orch_snare()
{
    const double dur = 0.20;
    NoiseGenerator ng(17u);
    Buffer buf = ng.render(dur, SR);
    SVFilter bp(SVFilter::Mode::BandPass, 2000.0, 2.0); bp.process(buf, SR);
    for (size_t i = 0; i < buf.size(); ++i)
        buf[i] *= (float)std::exp(-(double)i / SR * 26.0);
    Buffer body = make_buffer(dur, SR);
    Oscillator ob(WaveShape::Sine, 200.0, 0.40);
    for (size_t i = 0; i < body.size(); ++i)
        body[i] = ob.tick(SR) * (float)std::exp(-(double)i / SR * 38.0);
    mix_into(buf, body, 0.50f);
    normalize(buf, 0.70f);
    return buf;
}

static Buffer make_crash()
{
    const double dur = 2.00;
    NoiseGenerator ng(199u);
    Buffer buf = ng.render(dur, SR);
    HighPassFilter hpf(4500.0, SR); hpf.process(buf);
    BiquadEQ shim(BiquadEQ::Type::Peak, 7500.0, 2.5, 3.0);
    shim.process(buf, SR);
    for (size_t i = 0; i < buf.size(); ++i)
        buf[i] *= (float)std::exp(-(double)i / SR * 2.5);
    normalize(buf, 0.38f);
    return buf;
}

static Buffer make_hat()
{
    const double dur = 0.04;
    NoiseGenerator ng(7u);
    Buffer buf = ng.render(dur, SR);
    HighPassFilter hpf(9000.0, SR); hpf.process(buf);
    for (size_t i = 0; i < buf.size(); ++i)
        buf[i] *= (float)std::exp(-(double)i / SR * 65.0);
    normalize(buf, 0.25f);
    return buf;
}

static void print_help(const char* prog) {
    std::cout
        << "Bad Apple - Orchestral Arrangement\n"
        << "Usage:\n  " << prog << " [options]\n\n"
        << "  -o, --output <file>   Output WAV (default: badapple.wav)\n"
        << "      --play            Play after rendering\n"
        << "  -h, --help            Show help\n";
}

int main(int argc, char** argv)
{
    std::string output  = "badapple.wav";
    bool        do_play = false;

    for (int i = 1; i < argc; ++i) {
        std::string a = argv[i];
        if (a == "-o" || a == "--output") {
            if (i + 1 < argc) output = argv[++i];
            else { std::cerr << "Missing argument\n"; return 1; }
        } else if (a == "--play") {
            do_play = true;
        } else if (a == "-h" || a == "--help") {
            print_help(argv[0]); return 0;
        } else {
            std::cerr << "Unknown: " << a << "\n"; return 1;
        }
    }

    global_config().sample_rate = SR;
    global_config().channels    = 2;
    global_config().bits        = 16;

    constexpr double TOTAL_DUR = 218.0;
    const size_t total = (size_t)(TOTAL_DUR * SR);

    std::cout << "Bad Apple - Orchestral Arrangement\n"
              << "  138 BPM  |  " << std::fixed << std::setprecision(1)
              << TOTAL_DUR << " s\n\n";

    StereoBuffer master(total, 0.0f);

    const Buffer kick_buf  = make_timpani(73.4);
    const Buffer snare_buf = make_orch_snare();
    const Buffer hat_buf   = make_hat();
    const Buffer crash_buf = make_crash();

    std::cout << "  [1/14] Timpani / percussion...\n" << std::flush;
    for (int i = 0; i < kick_times_count;  ++i) mix_mono_at(master, kick_buf,  kick_times[i],  0.22f, SR);
    for (int i = 0; i < snare_times_count; ++i) mix_mono_at(master, snare_buf, snare_times[i], 0.14f, SR);
    for (int i = 0; i < hat_c_times_count; ++i) mix_mono_at(master, hat_buf,   hat_c_times[i], 0.07f, SR);
    for (int i = 0; i < crash_times_count; ++i) mix_mono_at(master, crash_buf, crash_times[i], 0.12f, SR);

    std::cout << "  [2/14] Contrabass (" << bass_notes_count << ")...\n" << std::flush;
    for (int i = 0; i < bass_notes_count; ++i) {
        const NoteEvent& n = bass_notes[i];
        mix_mono_at(master, make_contrabass(n.freq, n.dur, SR), n.t, 0.16f, SR);
    }

    std::cout << "  [3/14] Cello (" << cello_notes_count << ")...\n" << std::flush;
    for (int i = 0; i < cello_notes_count; ++i) {
        const NoteEvent& n = cello_notes[i];
        mix_mono_at(master, make_cello(n.freq, n.dur, SR), n.t, 0.14f, SR);
    }

    std::cout << "  [4/14] String pads (synth tracks, "
              << str_pad1_notes_count + str_pad2_notes_count
               + str_pad3_notes_count + str_pad4_notes_count << ")...\n" << std::flush;
    for (int i = 0; i < str_pad1_notes_count; ++i) {
        const NoteEvent& n = str_pad1_notes[i];
        StereoBuffer sb = make_string_pad(n.freq, n.dur, SR);
        mix_stereo_at(master, sb, n.t, 0.10f, SR);
    }
    for (int i = 0; i < str_pad2_notes_count; ++i) {
        const NoteEvent& n = str_pad2_notes[i];
        StereoBuffer sb = make_string_pad(n.freq, n.dur, SR);
        mix_stereo_at(master, sb, n.t, 0.09f, SR);
    }
    for (int i = 0; i < str_pad3_notes_count; ++i) {
        const NoteEvent& n = str_pad3_notes[i];
        StereoBuffer sb = make_string_pad(n.freq, n.dur, SR);
        mix_stereo_at(master, sb, n.t, 0.09f, SR);
    }
    for (int i = 0; i < str_pad4_notes_count; ++i) {
        const NoteEvent& n = str_pad4_notes[i];
        StereoBuffer sb = make_string_pad(n.freq, n.dur, SR);
        mix_stereo_at(master, sb, n.t, 0.08f, SR);
    }

    std::cout << "  [5/14] Viola (" << viola_notes_count << ")...\n" << std::flush;
    for (int i = 0; i < viola_notes_count; ++i) {
        const NoteEvent& n = viola_notes[i];
        mix_mono_at(master, make_viola(n.freq, n.dur, SR), n.t, 0.14f, SR);
    }

    std::cout << "  [6/14] Piano (" << piano_hi_notes_count + piano_lo_notes_count << ")...\n" << std::flush;
    for (int i = 0; i < piano_lo_notes_count; ++i) {
        const NoteEvent& n = piano_lo_notes[i];
        mix_mono_at(master, make_piano(n.freq, n.dur, SR), n.t, 0.12f, SR);
    }
    for (int i = 0; i < piano_hi_notes_count; ++i) {
        const NoteEvent& n = piano_hi_notes[i];
        mix_mono_at(master, make_piano(n.freq, n.dur, SR), n.t, 0.11f, SR);
    }

    std::cout << "  [7/14] French horns (" << horn1_notes_count + horn2_notes_count << ")...\n" << std::flush;
    for (int i = 0; i < horn1_notes_count; ++i) {
        const NoteEvent& n = horn1_notes[i];
        mix_mono_at(master, make_horn(n.freq, n.dur, SR), n.t, 0.14f, SR);
    }
    for (int i = 0; i < horn2_notes_count; ++i) {
        const NoteEvent& n = horn2_notes[i];
        mix_mono_at(master, make_horn(n.freq, n.dur, SR), n.t, 0.12f, SR);
    }

    std::cout << "  [8/14] Violins (" << violin_notes_count << ")...\n" << std::flush;
    for (int i = 0; i < violin_notes_count; ++i) {
        const NoteEvent& n = violin_notes[i];
        StereoBuffer sb = make_strings(n.freq, n.dur, SR);
        mix_stereo_at(master, sb, n.t, 0.16f, SR);
    }

    std::cout << "  [9/14] Alto sax / woodwind mid ("
              << alto_sax1_notes_count + alto_sax2_notes_count << ")...\n" << std::flush;
    for (int i = 0; i < alto_sax1_notes_count; ++i) {
        const NoteEvent& n = alto_sax1_notes[i];
        mix_mono_at(master, make_sax(n.freq, n.dur, SR), n.t, 0.12f, SR);
    }
    for (int i = 0; i < alto_sax2_notes_count; ++i) {
        const NoteEvent& n = alto_sax2_notes[i];
        mix_mono_at(master, make_sax(n.freq, n.dur, SR), n.t, 0.11f, SR);
    }

    std::cout << "  [10/14] Clarinets (" << clarinet1_notes_count + clarinet2_notes_count << ")...\n" << std::flush;
    for (int i = 0; i < clarinet1_notes_count; ++i) {
        const NoteEvent& n = clarinet1_notes[i];
        mix_mono_at(master, make_clarinet(n.freq, n.dur, SR), n.t, 0.12f, SR);
    }
    for (int i = 0; i < clarinet2_notes_count; ++i) {
        const NoteEvent& n = clarinet2_notes[i];
        mix_mono_at(master, make_clarinet(n.freq, n.dur, SR), n.t, 0.11f, SR);
    }

    std::cout << "  [11/14] Trumpets (" << trumpet1_notes_count + trumpet2_notes_count << ")...\n" << std::flush;
    for (int i = 0; i < trumpet1_notes_count; ++i) {
        const NoteEvent& n = trumpet1_notes[i];
        mix_mono_at(master, make_trumpet(n.freq, n.dur, SR), n.t, 0.13f, SR);
    }
    for (int i = 0; i < trumpet2_notes_count; ++i) {
        const NoteEvent& n = trumpet2_notes[i];
        mix_mono_at(master, make_trumpet(n.freq, n.dur, SR), n.t, 0.12f, SR);
    }

    std::cout << "  [12/14] Oboes (" << oboe1_notes_count + oboe2_notes_count << ")...\n" << std::flush;
    for (int i = 0; i < oboe1_notes_count; ++i) {
        const NoteEvent& n = oboe1_notes[i];
        mix_mono_at(master, make_oboe(n.freq, n.dur, SR), n.t, 0.12f, SR);
    }
    for (int i = 0; i < oboe2_notes_count; ++i) {
        const NoteEvent& n = oboe2_notes[i];
        mix_mono_at(master, make_oboe(n.freq, n.dur, SR), n.t, 0.11f, SR);
    }

    std::cout << "  [13/14] Soprano sax / flutes ("
              << soprano_sax_notes_count + flute1_notes_count + flute2_notes_count << ")...\n" << std::flush;
    for (int i = 0; i < soprano_sax_notes_count; ++i) {
        const NoteEvent& n = soprano_sax_notes[i];
        mix_mono_at(master, make_sax(n.freq, n.dur, SR), n.t, 0.12f, SR);
    }
    for (int i = 0; i < flute1_notes_count; ++i) {
        const NoteEvent& n = flute1_notes[i];
        mix_mono_at(master, make_flute(n.freq, n.dur, SR), n.t, 0.13f, SR);
    }
    for (int i = 0; i < flute2_notes_count; ++i) {
        const NoteEvent& n = flute2_notes[i];
        mix_mono_at(master, make_flute(n.freq, n.dur, SR), n.t, 0.12f, SR);
    }

    std::cout << "  [14/14] Piccolo (" << piccolo_notes_count << ")...\n" << std::flush;
    for (int i = 0; i < piccolo_notes_count; ++i) {
        const NoteEvent& n = piccolo_notes[i];
        mix_mono_at(master, make_piccolo(n.freq, n.dur, SR), n.t, 0.14f, SR);
    }

    std::cout << "\n  Master bus...\n" << std::flush;

    Reverb rvL; rvL.room_size = 0.88f; rvL.wet = 0.28f; rvL.dry = 0.88f; rvL.init(SR);
    Reverb rvR; rvR.room_size = 0.90f; rvR.wet = 0.28f; rvR.dry = 0.88f; rvR.init(SR);
    rvL.process(master.L);
    rvR.process(master.R);

    ParametricEQ eq;
    eq.low_shelf  = BiquadEQ(BiquadEQ::Type::LowShelf,  150.0, -5.0, 0.7);
    eq.peak       = BiquadEQ(BiquadEQ::Type::Peak,       500.0, -5.0, 1.5);
    eq.high_shelf = BiquadEQ(BiquadEQ::Type::HighShelf, 6000.0, -3.0, 0.7);
    eq.process(master, SR);

    distortion::apply_soft_clip(master.L, 2.50f);
    distortion::apply_soft_clip(master.R, 2.50f);

    fade_in(master,  0.30, SR);
    fade_out(master, 3.50, SR);

    normalize(master, 0.22f);
    clamp_buffer(master);

    std::cout << "  Writing: " << output << "\n";
    save_wav_stereo(master, output, SR);
    std::cout << "  Done.\n";

    if (do_play) {
        std::cout << "  Playing (press Enter to stop)...\n";
        PlaybackHandle h = play_async(master, SR);
        std::thread([h]() mutable { std::cin.get(); h.stop(); }).detach();
        h.wait();
    }

    return 0;
}
